import{_ as a,o as e,c as d,a2 as l}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"设计原则","description":"","frontmatter":{"title":"设计原则"},"headers":[],"relativePath":"guide/principles.md","filePath":"guide/principles.md","lastUpdated":null}'),r={name:"guide/principles.md"};function o(i,t,s,h,n,c){return e(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to &quot;设计原则&quot;">​</a></h1><p><span class="level level-must">🔴 第 1 节 · 强制</span></p><p>以下 4 条原则是全规范的总纲，其余章节的数值与组件规则都可以视为它们的落地方式。当具体规则未覆盖某个场景时，回到这 4 条来判断。</p><h2 id="原则清单" tabindex="-1">原则清单 <a class="header-anchor" href="#原则清单" aria-label="Permalink to &quot;原则清单&quot;">​</a></h2><ul class="rules"><li class="must"><b>一致优先</b>：相同功能在不同页面保持相同外观与交互。</li><li class="recommend"><b>克制装饰</b>：颜色、阴影、动效服务于信息层级。</li><li class="must"><b>状态完整</b>：必须定义默认、悬停、按下、禁用、加载、错误等状态。</li><li class="must"><b>可验证</b>：数值和规则应能被代码检查或走查清单验证。</li></ul><h2 id="逐条说明" tabindex="-1">逐条说明 <a class="header-anchor" href="#逐条说明" aria-label="Permalink to &quot;逐条说明&quot;">​</a></h2><h3 id="一致优先-🔴" tabindex="-1">一致优先 🔴 <a class="header-anchor" href="#一致优先-🔴" aria-label="Permalink to &quot;一致优先 🔴&quot;">​</a></h3><p>同一类信息在系统各处使用同一套表达：主操作永远是主按钮，危险操作永远是红色，删除确认永远在弹窗右侧。用户不需要在页面之间重新学习。</p><p>判断方法：把两个页面的同类元素截图并排放，如果不看上下文分不出哪个属于哪个页面，说明一致。</p><h3 id="克制装饰-🟡" tabindex="-1">克制装饰 🟡 <a class="header-anchor" href="#克制装饰-🟡" aria-label="Permalink to &quot;克制装饰 🟡&quot;">​</a></h3><p>颜色、阴影、动效只用来表达层级和状态，不用于表达「好看」。一个页面里出现三种以上的强调色，通常是装饰过度。</p><ul><li>阴影只用于浮层（卡片、弹窗、下拉），平面内容不加阴影；</li><li>动效只用于状态切换与空间关系，时长统一 <code>200ms</code>；</li><li>同屏最多一个主按钮（见<a href="/components/button.html">按钮</a>）。</li></ul><h3 id="状态完整-🔴" tabindex="-1">状态完整 🔴 <a class="header-anchor" href="#状态完整-🔴" aria-label="Permalink to &quot;状态完整 🔴&quot;">​</a></h3><p>组件交付时必须同时交付状态。以下 6 个状态是底线：</p><table tabindex="0"><thead><tr><th>状态</th><th>触发条件</th><th>设计要求</th></tr></thead><tbody><tr><td>Default</td><td>无交互</td><td>基准样式</td></tr><tr><td>Hover</td><td>鼠标悬停</td><td>背景或边框变化，不明显改变尺寸</td></tr><tr><td>Active</td><td>按下</td><td>比 hover 更深一档的反馈</td></tr><tr><td>Disabled</td><td>不可用</td><td>降低对比度，<code>cursor: not-allowed</code></td></tr><tr><td>Loading</td><td>异步进行中</td><td>阻止重复提交，给出进度反馈</td></tr><tr><td>Error</td><td>校验失败</td><td>用 <code>--color-danger</code> 表达，并说明原因</td></tr></tbody></table><h3 id="可验证-🔴" tabindex="-1">可验证 🔴 <a class="header-anchor" href="#可验证-🔴" aria-label="Permalink to &quot;可验证 🔴&quot;">​</a></h3><p>规范里写下的每一条都要能被检查，否则无法执行。可验证的写法：</p><ul><li>✅「正文 14px / 行高 1.5」——可被样式检查；</li><li>✅「同一区域最多一个主按钮」——可被走查；</li><li>❌「界面要清爽美观」——不可验证。</li></ul><h2 id="适用范围" tabindex="-1">适用范围 <a class="header-anchor" href="#适用范围" aria-label="Permalink to &quot;适用范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>适用端</td><td>Web 端（PC 浏览器）</td></tr><tr><td>适用角色</td><td>UI 设计师、前端开发、测试、产品经理</td></tr><tr><td>不在范围</td><td>移动端、小程序、原生客户端、宣传物料</td></tr><tr><td>唯一源文件</td><td><code>公司产品 UI 设计规范.md</code>；Trae 规则从第 9 节派生，不单独维护数值</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">使用建议</p><p>先读本节建立判断标准，再按 <a href="/foundation/color.html">色彩</a> → <a href="/foundation/typography.html">排版</a> → <a href="/foundation/spacing.html">间距</a> → <a href="/components/button.html">组件</a> 的顺序落地。颜色和间距是一切组件的基础，顺序反过来会返工。</p></div>',21)])])}const b=a(r,[["render",o]]);export{u as __pageData,b as default};
